#!/bin/bash
# === Ozawa Traders lightbox upgrade (power-cabinet, micro-feeder, dilution-tank) ===
# Paste this entire script into AWS Session Manager (logged in as ec2-user).
set -e
APP_DIR=/var/www/ozawatraders
TS=$(date +%Y%m%d-%H%M%S)
BACKUP_DIR=$APP_DIR/.deploy-backup-$TS

echo "==> Backup to $BACKUP_DIR"
mkdir -p "$BACKUP_DIR/views/partials"
cp "$APP_DIR/views/partials/lightbox.ejs" "$BACKUP_DIR/views/partials/lightbox.ejs"
cp "$APP_DIR/views/category.ejs"          "$BACKUP_DIR/views/category.ejs"

echo "==> Writing new lightbox.ejs"
cat > /tmp/lightbox.ejs.b64 <<'B64END'

B64END
base64 -d /tmp/lightbox.ejs.b64 > "$APP_DIR/views/partials/lightbox.ejs"
rm /tmp/lightbox.ejs.b64

echo "==> Patching category.ejs (adds lightbox-gallery class on slider)"
if grep -q 'catSlider[^>]*lightbox-gallery' "$APP_DIR/views/category.ejs"; then
    echo "   already patched, skipping"
elif grep -q 'id="catSlider"' "$APP_DIR/views/category.ejs"; then
    sed -i '/id="catSlider"/ s/ bg-navy-900">/ bg-navy-900 lightbox-gallery">/' "$APP_DIR/views/category.ejs"
    grep 'catSlider[^>]*lightbox-gallery' "$APP_DIR/views/category.ejs" > /dev/null && echo "   patched OK" || { echo "   ERROR: sed did not apply"; exit 1; }
else
    echo "   ERROR: id=\"catSlider\" not found"; exit 1
fi

echo "==> Restarting PM2 (clears production EJS view cache)"
pm2 restart ozawatraders 2>/dev/null || pm2 restart all

echo "==> Waiting 3s then verifying live URLs"
sleep 3
for p in /power-cabinet /micro-feeder /dilution-tank; do
    code=$(curl -sk -o /dev/null -w '%{http_code}' "https://ozawatraders.org$p")
    frame=$(curl -sk "https://ozawatraders.org$p" | grep -c 'id="lightbox-frame"' || true)
    wired=$(curl -sk "https://ozawatraders.org$p" | grep -c 'catSlider[^>]*lightbox-gallery' || true)
    printf "   %-16s status:%s  lightbox-frame:%s  slider-wired:%s\n" "$p" "$code" "$frame" "$wired"
done

echo "==> Done. Backup at $BACKUP_DIR"